    public static ModuleIcon? Find(string? key) => All.FirstOrDefault(i => i.Key == key);
    public static ModuleIcon Default(string id) => Find(id.ToUpperInvariant() switch
    {
        "GAME" => "core", "VENDORS" => "vendors", "ATLAS" => "atlas", "HARVEST" => "harvest",
        "DELVE" => "delve", "COMMANDS" => "commands", "BENCH" => "bench",
        "HEIST" => "lockoutline", "COSMETICS" => "paletteoutline", "TATTOOS" => "fleurdelis",
        "UNIQUEBELTS" => "belt", "NPCDIALOGUE" => "chatoutline", "PANTHEON" => "crownoutline",
        "SOCIAL" => "accountmultipleoutline", "HIDEOUTEDITING" => "homeeditoutline", "PORTALS" => "portal",
        "QUESTOBJECTS" => "bookopenpagevariantoutline", "NESSADEVELOPMENTTABS" => "bugoutline",
        "PHRECIAASCENDANCIES" => "stairsup", "PLAYERBOTS" => "robotoutline", "RUTHLESS" => "skullcrossbonesoutline",
        "SURVIVORSREWARDS" => "giftoutline", "SURVIVORSRUN" => "waves", "SURVIVORSSKILLS" => "magicstaff",
        _ => "modules"
    })!;
    public static string Scope => OperatingSystem.IsWindows() ? Environment.CurrentDirectory.ToUpperInvariant() : Environment.CurrentDirectory;
    public static ModuleIcon Resolve(Settings settings, string id) => (settings.ModuleIcons ??= []).TryGetValue(Scope, out var icons)
        && icons is not null && icons.TryGetValue(id.ToUpperInvariant(), out var key) && Find(key) is { } icon ? icon : Default(id);
    public static string Resource(string id) => "Waypoint.ModuleIcon." + Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(
        System.Text.Encoding.UTF8.GetBytes(Scope + "\n" + id.ToUpperInvariant())));
}
